"  const fetchPieData = async () => {
    if (!isAuthenticated) return;
    const start = pieStartDate || new Date().toISOString().split('T')[0];
    const end = pieEndDate || new Date().toISOString().split('T')[0];

    let rangeOrders = [];
    if (navigator.onLine) {
      try {
        const res = await posService.getAllOrders({
          startDate: start + ' 00:00:00',
          endDate: end + ' 23:59:59'
        });
        rangeOrders = res.data || [];
      } catch (err) {
        console.warn("Failed to fetch pie chart data from server, falling back to local orders:", err);
        rangeOrders = recentOrders || [];
      }
    } else {
      rangeOrders = recentOrders || [];
    }

    if (!rangeOrders || rangeOrders.length === 0) return;

    const filtered = rangeOrders.filter(o => {
      if (o.status === 'CANCELLED' || o.status === 'DELETED') return false;
      const date = (o.created_at || o.timestamp || '').split('T')[0];
      return date >= start && date <= end;
    });

    const allItems = filtered.flatMap(o => o.items || []);
    const aggregated = allItems.reduce((acc, item) => {
      const name = item.product_name || item.name;
      const qty = item.quantity || item.qty || 1;
      const existing = acc.find(i => i.name === name);
      if (existing) {
        existing.qty += qty;
      } else {
        acc.push({ name, qty });
      }
      return acc;
    }, []);

    const top = aggregated.sort((a, b) => b.qty - a.qty).slice(0, parseInt(pieLimit) || 5);
    setPieItems(top);
  };"
